/** Shared provider naming contract for canonical and renderer preflight. */
export function validOneNoteStructureName(action:string,name:unknown):boolean {
 const notebook=action==='notes.notebook.create',limit=notebook?128:50;
 const forbidden=notebook?/[?*\\/:<>|'"\u0000-\u001f\u007f]/:/[?*\\/:<>|&#'%~\u0000-\u001f\u007f]/;
 return typeof name==='string'&&!!name.trim()&&Array.from(name).length<=limit&&!forbidden.test(name)&&!/[\ud800-\udbff](?![\udc00-\udfff])|(?<![\ud800-\udbff])[\udc00-\udfff]/.test(name);
}

